 main_tables.append(table('Table 2 Paired annual eye care estimates',['Measure','2025 n/N','2025 % (95% CI)','2022 n/N','2022 % (95% CI)'],rows,[1.4,1.1,1.45,1.1,1.45],'The first seven measures use all complete pairs. Missed among either is photography only divided by either-modality contact. Photo among no dilation is photography only divided by all respondents without annual dilation. Neither indicates absence of reported annual contact by both questions, not absence of indicated screening. Confidence intervals account for weights, stratification, PSU variation and paired definitions. Years represent different participating-state populations.'))
 word=lambda s:len(re.findall(r"\b[\w]+(?:[’'-][\w]+)*\b",s))
