 x=dict(title=title,subtitle='Paired analysis of 2025 BRFSS with temporal corroboration in a separate 2022 sample',main_word_count=main_words,abstract_word_count=abswords,abstract=abstract,sections=sections,declarations=declarations,references=reference_list,tables=main_tables,figures=figures)
