  for group in pro[pro.year.eq(y)].group.unique():
   r=g(y,'Photography only',group); b=g(y,'Photo among no dilation',group)
   def subgroup(value):return ci(value) if value.flag=='adequate' else f'{value.estimate:.1f} (limited)'
